                string helper=sample.Item1.StartsWith("monarch")?"The Monarch":"The Initiative";var card=view.players.SelectMany(p=>p.effectMarkers).Single(c=>c.helperArtName==helper);var tile=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="Card_"+card.id);var image=tile.Find("Visual/Border/Face").GetComponent<Image>();Check(SpecialEffectArt.TryLoad(helper,out var expected)&&image.sprite==expected&&image.preserveAspect,"Wrong helper artwork");float y=RectTransformUtility.WorldToScreenPoint(null,tile.position).y;Check((card.ownerSeat==view.seat)==(y<Screen.height*.5f),"Helper stayed in former owner area");
