                if(lang=="zh-CN"&&!other&&sample.Item2=="transferred"){ScreenCapture.CaptureScreenshot(Output+"/"+helper+"-transferred.png");yield return Frame();}File.AppendAllText(Output+"/steps.log",lang+" "+sample.Item1+"/"+sample.Item2+" seat="+view.seat+" helper="+card.id+" PASS\n");
            }
