                var meta=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/player-status-1006/native/"+sample.Item1+"-result.json"));string path=meta.folder+"/"+sample.Item2+".json";File.Copy(path,Output+"/inputs/regression-"+sample.Item1+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",path+"\t"+Hash(path)+"\n");var view=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(path));ui.Present(view,1,false,null,null,"");yield return Frame();var marker=view.players.SelectMany(p=>p.effectMarkers).Concat(view.globalEffects??Array.Empty<ForgeCardView>()).First(c=>c.helperArtName is "Day" or "Max Speed!");string text=(string)typeof(ForgeBattlefieldController).GetMethod("MarkerRules",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{marker});Check(text.Contains(marker.helperArtName=="Day"?(lang=="zh-CN"?"当前为白昼":lang=="ja-JP"?"現在は昼":"currently day"):lang=="en-US"?"Speed: 4":"速度：4"),"Adjacent marker regression");
